// Generate potential match pairs avoiding duplicates
const users = $input.first().json.records || [];
const existingMatches = $input.last().json.records || [];

// Create a set of existing match pairs for quick lookup
const matchedPairs = new Set();
existingMatches.forEach(match => {
  const user1 = match.fields['User 1'] ? match.fields['User 1'][0] : null;
  const user2 = match.fields['User 2'] ? match.fields['User 2'][0] : null;
  if (user1 && user2) {
    const pair = [user1, user2].sort().join('|');
    matchedPairs.add(pair);
  }
});

// Generate all possible pairs that haven't been matched
const potentialMatches = [];
for (let i = 0; i < users.length; i++) {
  for (let j = i + 1; j < users.length; j++) {
    const user1 = users[i];
    const user2 = users[j];
    const pairKey = [user1.id, user2.id].sort().join('|');

    // Only include if not already matched
    if (!matchedPairs.has(pairKey)) {
      potentialMatches.push({
        user1: {
          id: user1.id,
          name: user1.fields['Full Name'] || 'Unknown',
          location: user1.fields['Location'] || '',
          job: user1.fields['Job Title'] || '',
          company: user1.fields['Company'] || '',
          industry: user1.fields['Industry'] || '',
          hobbies: user1.fields['Hobbies'] || [],
          interests: user1.fields['Interests'] || '',
          skills: user1.fields['Skills'] || [],
          experience: user1.fields['Years Experience'] || 0,
          timezone: user1.fields['Timezone'] || '',
          lookingFor: user1.fields["What I'm Looking For"] || '',
          discordId: user1.fields['Discord ID'] || ''
        },
        user2: {
          id: user2.id,
          name: user2.fields['Full Name'] || 'Unknown',
          location: user2.fields['Location'] || '',
          job: user2.fields['Job Title'] || '',
          company: user2.fields['Company'] || '',
          industry: user2.fields['Industry'] || '',
          hobbies: user2.fields['Hobbies'] || [],
          interests: user2.fields['Interests'] || '',
          skills: user2.fields['Skills'] || [],
          experience: user2.fields['Years Experience'] || 0,
          timezone: user2.fields['Timezone'] || '',
          lookingFor: user2.fields["What I'm Looking For"] || '',
          discordId: user2.fields['Discord ID'] || ''
        }
      });
    }
  }
}

return potentialMatches.map(match => ({ json: match }));

