// Parse AI response and filter high-quality matches
const items = $input.all();
const goodMatches = [];

items.forEach(item => {
  try {
    // Extract JSON from AI response
    const aiResponse = item.json.response || item.json.output || '';
    let matchData;

    // Try to parse as JSON
    if (typeof aiResponse === 'string') {
      const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        matchData = JSON.parse(jsonMatch[0]);
      }
    } else {
      matchData = aiResponse;
    }

    if (matchData && matchData.score >= 60) { // Only matches with 60+ score
      goodMatches.push({
        json: {
          user1_id: item.json.user1.id,
          user2_id: item.json.user2.id,
          user1_discord: item.json.user1.discordId,
          user2_discord: item.json.user2.discordId,
          user1_name: item.json.user1.name,
          user2_name: item.json.user2.name,
          match_score: matchData.score,
          match_reason: matchData.reason,
          confidence: matchData.confidence || 'medium'
        }
      });
    }
  } catch (error) {
    console.error('Error parsing match:', error);
  }
});

// Sort by score descending and return top 10 matches
goodMatches.sort((a, b) => b.json.match_score - a.json.match_score);
return goodMatches.slice(0, 10);

